const nums = [6, 1, 3, 9, 4, 2];
const target = 10;
const k = 2;

console.log(`Pairs that sum to ${target}:`);
for (let i = 0; i < nums.length; i++) {
  for (let j = i + 1; j < nums.length; j++) {
    if (nums[i] + nums[j] === target) {
      console.log(`${nums[i]} + ${nums[j]}`);
    }
  }
}

let drops = 0;
for (let i = 0; i < nums.length - 1; i++) {
  if (nums[i + 1] < nums[i]) {
    drops++;
  }
}
console.log(`Drops between neighbors: ${drops}`);

let windowSum = 0;
for (let i = 0; i < k; i++) {
  windowSum += nums[i];
}
let smallest = windowSum;
for (let i = k; i < nums.length; i++) {
  windowSum += nums[i] - nums[i - k];
  if (windowSum < smallest) {
    smallest = windowSum;
  }
}
console.log(`Smallest sum of ${k} in a row: ${smallest}`);
